import 'package:pocketbase/pocketbase.dart';

final pb = PocketBase('http://127.0.0.1:8090');

// authenticate
final user = await pb.collection('users').authWithPassword('test@example.com', '123456');

// get list
final list = await pb.collection('example').getList(page:1, perPage:20);

// realtime
pb.collection('example').subscribe('*', (e){print(e.action);});
